/* One compact action menu per task, preserving the original permission checks. */
(()=>{'use strict';const shared=document.body.classList.contains('shared-app');let opener=null;const menu=document.createElement('div');menu.className='task-overflow-menu';menu.id='taskOverflowMenu';menu.hidden=true;menu.setAttribute('role','menu');menu.dir='rtl';document.body.append(menu);
function close(focus=false){menu.hidden=true;menu.replaceChildren();if(opener){opener.setAttribute('aria-expanded','false');if(focus&&opener.isConnected)opener.focus()}opener=null}
function open(button,sources){if(opener===button){close();return}close();opener=button;button.setAttribute('aria-expanded','true');for(const source of sources){const item=document.createElement('button');item.type='button';item.setAttribute('role','menuitem');item.textContent=source.textContent.trim();item.disabled=source.disabled;item.className=source.matches('.task-row-delete')?'danger':'';item.onclick=e=>{e.stopPropagation();close();if(source.isConnected&&!source.disabled)source.click()};menu.append(item)}menu.hidden=false;menu.style.visibility='hidden';menu.style.left='0';menu.style.top='0';const rect=button.getBoundingClientRect(),mr=menu.getBoundingClientRect(),scale=mr.width/(menu.offsetWidth||mr.width)||1;const x=Math.max(8,Math.min(rect.left,innerWidth-mr.width-8)),y=rect.bottom+mr.height+8<innerHeight?rect.bottom+5:Math.max(8,rect.top-mr.height-5);menu.style.left=x/scale+'px';menu.style.top=y/scale+'px';menu.style.visibility='visible';menu.querySelector('button:not(:disabled)')?.focus()}
function collect(){if(opener&&!opener.isConnected)close();const area=document.querySelector(shared?(window.SAMANDIS_PERSONAL_MODE?'#sharedApp':'#sharedContent'):'#workspace');if(!area)return;area.querySelectorAll('.clarity-table tbody tr,.desk-task-card,.personal-task-row').forEach(row=>{if(row.matches('.personal-task-row')&&!row.querySelector('.task-row-edit')&&row.querySelector('[data-personal-trash]')?.textContent.trim()!=='بازیابی'){const title=row.querySelector('.personal-task-title');if(title){const edit=document.createElement('button');edit.type='button';edit.className='task-row-edit';edit.textContent='ویرایش';edit.onclick=()=>title.click();row.append(edit)}}const sources=[...row.querySelectorAll('.row-upload,.approve-inline,.task-row-edit,.task-row-delete')];if(!sources.length)return;row.classList.add('has-task-overflow');sources.forEach(b=>b.classList.add('task-overflow-source'));let button=row.querySelector('.task-overflow-button');if(!button){button=document.createElement('button');button.type='button';button.className='task-overflow-button';button.textContent='⋯';button.setAttribute('aria-haspopup','menu');button.setAttribute('aria-controls',menu.id);button.setAttribute('aria-expanded','false');const title=row.querySelector('.task-title,.shared-task-title,.personal-task-title')?.textContent.trim()||'کار';button.setAttribute('aria-label','گزینه‌های '+title);(row.matches('tr')?row.lastElementChild:row).append(button)}button.onclick=e=>{e.preventDefault();e.stopPropagation();open(button,sources)};button.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();open(button,sources)}}})}
menu.onkeydown=e=>{const items=[...menu.querySelectorAll('button:not(:disabled)')],i=items.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();close(true)}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus()}else if(e.key==='Tab')close()};document.addEventListener('click',e=>{if(!menu.contains(e.target))close()});window.addEventListener('resize',()=>close());document.addEventListener('scroll',e=>{if(!menu.contains(e.target))close()},true);
const oldTasks=renderTasks;renderTasks=function(...args){close();const result=oldTasks(...args);collect();return result};const oldRender=render;render=function(...args){close();const result=oldRender(...args);collect();return result};collect();
})();
